  [ex("Sientes mareo y debilidad al jugar al sol del mediodía. ¿Qué haces primero: A) me detengo y busco sombra; B) sigo jugando para terminar?", "A", "Hay que parar y bajar la temperatura del cuerpo."),
   ex("¿A qué hora conviene evitar el ejercicio fuerte al aire libre: A) en el calor del mediodía; B) en la mañana temprano?", "A", "El mediodía tiene más calor y más radiación solar."),
   ex("Tu amigo te ofrece beber de su botella. ¿Qué es mejor: A) usar mi propia botella; B) compartir el mismo envase?", "A", "Cada persona usa su botella por higiene.")],
