  [arith("Si en una tarde de actividad al aire libre usas protector solar dos veces con 2 horas entre ambas, ¿cuántos minutos hay entre ambas aplicaciones?", "2*60", "Una hora son 60 minutos y son 2 horas.", " minutos"),
   ex("Llevas una botella para una sesión de 40 minutos con sorbos cada 20 minutos. ¿Cuántas pausas de agua hay durante la sesión?", "2", "En 40 minutos hay dos intervalos de 20 minutos.")],
